interface Options {
  // 平台 -> 主页链接,顺序即展示顺序
  links: Record<string, string>
}

export default ((opts?: Options) => {
  const SocialLinks: QuartzComponent = ({ displayClass }: QuartzComponentProps) => {
    const links = opts?.links ?? {}
    return (
      <div class={classNames(displayClass, "social-links")}>
        {Object.entries(links).map(([kind, url]) => {
          const icon = icons[kind]
          if (!icon) return null
          return (
            <a
              href={url}
              class={`social-link social-link--${kind}`}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={icon.label}
              title={icon.label}
            >
              <svg
                role="img"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
                fill="currentColor"
                width="16"
                height="16"
              >
                <path d={icon.path} />
              </svg>
            </a>
          )
        })}
      </div>
    )
  }

  SocialLinks.css = `
.social-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  justify-content: flex-start;
  /* 标题前有羽毛 emoji + 空格,留左缩进让图标起点对齐到 “W” 文字下方 */
  padding-left: 21px;
}
/* 图标行外层 Flex 容器:贴近标题,与搜索行一致的负边距 */
.flex-component:has(.social-links) {
  margin-top: -0.8rem;
}
.social-links .social-link {
  color: var(--gray);
  display: inline-flex;
  transition: color 0.2s ease, transform 0.2s ease;
}
.social-links .social-link:hover {
  transform: translateY(-2px);
}
.social-links .social-link--github:hover {
  color: var(--dark);
}
.social-links .social-link--youtube:hover {
  color: #ff0000;
}
.social-links .social-link--bilibili:hover {
  color: #00aeec;
}
.social-links .social-link--xiaohongshu:hover {
  color: #ff2442;
}
.social-links .social-link--rss:hover {
  color: #1e80ff;
}
/* RSS glyph 把 24x24 viewBox 填满、没有内部留白,光学上比其他图标大一圈,缩小补偿 */
.social-links .social-link--rss svg {
  width: 11px;
  height: 11px;
}
`

  return SocialLinks
}) satisfies QuartzComponentConstructor
